 if(!idOk(orderId)||version!==undefined&&!/^\d+$/.test(String(version)))return res.status(400).json({message:'Invalid order or quotation version'});
 try{const dealer=isDealer(req)?await dealerFor(req):null;const result=await connection.query(`SELECT o.*,d.user_id AS dealer_user_id,d.business_name,d.contact_name,d.mobile,d.email,d.billing_address,d.tax_id AS dealer_tax_id,s.name AS store_name,s.legal_name,s.logo_url,s.address AS store_address,s.city,s.state,s.pin_code,s.phone,s.email AS store_email,s.gstin,s.terms_and_conditions,q.id AS quote_id,q.version,q.quotation_number AS quote_number,q.subtotal AS quote_subtotal,q.transport_charge AS quote_transport,q.discount_amount AS quote_discount,q.tax_amount AS quote_tax,q.grand_total AS quote_total,q.items_snapshot,q.document_snapshot AS quote_document,q.billing_address_snapshot AS quote_billing,q.delivery_address_snapshot AS quote_delivery,q.valid_until,q.expected_delivery_date,q.created_at AS quote_created_at FROM dealer_orders o JOIN dealer_profiles d ON d.id=o.dealer_id JOIN stores s ON s.id=o.store_id JOIN dealer_order_quotations q ON q.order_id=o.id AND ($3::int IS NULL OR q.version=$3) WHERE o.id=$1 AND ($2::bigint IS NULL OR o.dealer_id=$2) ORDER BY q.version DESC LIMIT 1`,[orderId,dealer?.id||null,version??null]);if(!result.rowCount)return res.status(404).json({message:'Quotation not found'});const row=result.rows[0],snapshot=row.quote_document||{},store=snapshot.store||{},party=snapshot.dealer||{};const buffer=await dealerQuotationPdf({order:row,quote:{quotation_number:row.quote_number,subtotal:row.quote_subtotal,transport_charge:row.quote_transport,discount_amount:row.quote_discount,tax_amount:row.quote_tax,grand_total:row.quote_total,items_snapshot:row.items_snapshot,billing_address_snapshot:row.quote_billing,delivery_address_snapshot:row.quote_delivery,valid_until:row.valid_until,expected_delivery_date:row.expected_delivery_date,created_at:row.quote_created_at},items:row.items_snapshot,store:{name:store.name||row.store_name,legal_name:store.legalName||row.legal_name,logo_url:store.logoUrl||row.logo_url,address:store.address||row.store_address,city:store.city||row.city,state:store.state||row.state,pin_code:store.pinCode||row.pin_code,phone:store.phone||row.phone,email:store.email||row.store_email,gstin:store.gstin||row.gstin,terms_and_conditions:store.terms},dealer:{business_name:party.businessName||row.business_name,contact_name:party.contactName||row.contact_name,mobile:party.mobile||row.mobile,email:party.email||row.email,tax_id:party.taxId||row.dealer_tax_id}});res.setHeader('Content-Type','application/pdf');res.setHeader('Content-Disposition',`attachment; filename="${row.quote_number}.pdf"`);res.send(buffer);}
