const payableStatuses=['CONFIRMED','PROCESSING','READY_TO_DISPATCH','SHIPPED','DELIVERED'];
const validMoney=value=>/^\d{1,14}(?:\.\d{1,2})?$/.test(String(value??''))&&Number(value)>0;
export async function createManualUpiAttempt(req,res){
 if(!isDealer(req))return res.status(403).json({message:'Dealer access is required'});if(!idOk(req.params.id))return res.status(400).json({message:'Invalid order ID'});
 const c=await connection.connect();try{await c.query('BEGIN');const r=await c.query(`SELECT o.*,q.grand_total AS accepted_total,d.customer_id,d.account_status,s.is_active AS store_active,s.name AS store_name,s.invoice_payment_details,s.dealer_partial_payments_enabled FROM dealer_orders o JOIN dealer_profiles d ON d.id=o.dealer_id JOIN stores s ON s.id=o.store_id JOIN dealer_order_quotations q ON q.order_id=o.id AND q.version=o.quotation_version WHERE o.id=$1 AND d.user_id=$2 FOR UPDATE OF o`,[req.params.id,req.user.id]);if(!r.rowCount){await c.query('ROLLBACK');return res.status(404).json({message:'Order not found'});}const o=r.rows[0];if(o.account_status!=='active'||!o.store_active||!payableStatuses.includes(o.status)||o.payment_method!=='UPI'){await c.query('ROLLBACK');return res.status(409).json({message:'This order is not eligible for direct UPI payment'});}if(!o.customer_id){await c.query('ROLLBACK');return res.status(409).json({message:'Link this dealer to an active customer ledger account before paying'});}const upiId=String(o.invoice_payment_details?.upiId||'').trim();if(!/^[A-Za-z0-9._-]{2,128}@[A-Za-z0-9.-]{2,64}$/.test(upiId)){await c.query('ROLLBACK');return res.status(503).json({message:'Store receiving UPI details are not configured'});}const paid=await c.query(`SELECT COALESCE(sum(amount),0)::numeric(18,2) amount FROM payments WHERE dealer_order_id=$1 AND direction='in' AND status='posted'`,[o.id]);const due=Number((await c.query('SELECT GREATEST($1::numeric-$2::numeric,0)::numeric(18,2) amount',[o.accepted_total,paid.rows[0].amount])).rows[0].amount);if(due<=0){await c.query('ROLLBACK');return res.status(409).json({message:'No payment balance is due'});}const pending=await c.query(`SELECT attempt_reference,requested_amount,status FROM dealer_manual_payment_claims WHERE order_id=$1 AND status IN ('initiated','pending_verification') ORDER BY id DESC LIMIT 1`,[o.id]);if(pending.rowCount){const claim=pending.rows[0];if(claim.status==='pending_verification'){await c.query('ROLLBACK');return res.status(409).json({message:'Your payment details are awaiting Admin verification. Do not pay again.',paymentStatus:'PENDING_VERIFICATION'});}if(Number(claim.requested_amount)>due){await c.query('ROLLBACK');return res.status(409).json({message:'The order balance changed; refresh and start a new payment attempt'});}await c.query('COMMIT');const amount=String(claim.requested_amount);return res.json({attemptReference:claim.attempt_reference,amount,upiId,payeeName:o.store_name,upiUri:upiUri(upiId,o.store_name,amount,`DO-${o.order_number}-${claim.attempt_reference.slice(0,8)}`),due,partialPaymentsEnabled:o.dealer_partial_payments_enabled});}
 const chosen=req.body?.amount===undefined?due.toFixed(2):String(req.body.amount);if(!validMoney(chosen)||Number(chosen)>due||(!o.dealer_partial_payments_enabled&&Number(chosen)!==due)){await c.query('ROLLBACK');return res.status(400).json({message:o.dealer_partial_payments_enabled?'Payment amount must be positive and no greater than the outstanding balance':'Store policy requires payment of the full outstanding balance'});}const ref=`DUPI-${randomUUID()}`;await c.query(`INSERT INTO dealer_manual_payment_claims(order_id,dealer_id,store_id,attempt_reference,requested_amount,status) VALUES($1,$2,$3,$4,$5,'initiated')`,[o.id,o.dealer_id,o.store_id,ref,chosen]);const uri=upiUri(upiId,o.store_name,chosen,`DO-${o.order_number}-${ref.slice(-8)}`);await c.query(`INSERT INTO audit_logs(store_id,user_id,action,entity_type,entity_id,after_data) VALUES($1,$2,'dealer.payment.upi_attempt_created','dealer_order',$3,$4)`,[o.store_id,req.user.id,o.id,{attemptReference:ref,amount:chosen}]);await c.query('COMMIT');return res.status(201).json({attemptReference:ref,amount:chosen,upiId,payeeName:o.store_name,upiUri:uri,due,partialPaymentsEnabled:o.dealer_partial_payments_enabled});}catch(e){await c.query('ROLLBACK').catch(()=>{});console.error('Manual UPI attempt failed:',e.message);return res.status(500).json({message:'Unable to create UPI payment attempt'});}finally{c.release();}
}
function upiUri(upiId,payeeName,amount,reference){const params=new URLSearchParams({pa:upiId,pn:payeeName,am:String(amount),cu:'INR',tn:reference});return `upi://pay?${params.toString()}`;}
export async function submitManualUpiClaim(req,res){
 if(!isDealer(req))return res.status(403).json({message:'Dealer access is required'});const id=req.params.id,ref=String(req.params.attemptReference||''),utr=String(req.body?.utr||'').trim();const amount=String(req.body?.amount??'');const paidAt=req.body?.paidAt;
 if(!idOk(id)||!/^DUPI-[0-9a-f-]{36}$/i.test(ref)||utr.length<6||utr.length>80||!/^[A-Za-z0-9-]+$/.test(utr)||!validMoney(amount)||!paidAt||Number.isNaN(Date.parse(paidAt)))return res.status(400).json({message:'Enter a valid amount, UTR, and payment date'});
 let screenshot=null,mime=null;if(req.body?.screenshotData){mime=String(req.body.screenshotMime||'');if(!['image/png','image/jpeg','image/webp'].includes(mime)||typeof req.body.screenshotData!=='string'||!/^[A-Za-z0-9+/]+={0,2}$/.test(req.body.screenshotData)){return res.status(400).json({message:'Payment screenshot must be a valid PNG, JPEG, or WebP image'});}screenshot=Buffer.from(req.body.screenshotData,'base64');if(!screenshot.length||screenshot.length>1024*1024)return res.status(400).json({message:'Payment screenshot must be no larger than 1 MB'});}
 const c=await connection.connect();try{await c.query('BEGIN');const r=await c.query(`SELECT a.*,o.status AS order_status,o.payment_method,o.quotation_version,o.store_id,o.grand_total,q.grand_total AS accepted_total,d.user_id,d.account_status,s.is_active AS store_active,s.dealer_partial_payments_enabled FROM dealer_manual_payment_claims a JOIN dealer_orders o ON o.id=a.order_id JOIN dealer_profiles d ON d.id=a.dealer_id JOIN stores s ON s.id=a.store_id JOIN dealer_order_quotations q ON q.order_id=o.id AND q.version=o.quotation_version WHERE a.order_id=$1 AND a.attempt_reference=$2 AND d.user_id=$3 FOR UPDATE OF a,o`,[id,ref,req.user.id]);if(!r.rowCount){await c.query('ROLLBACK');return res.status(404).json({message:'Payment attempt not found'});}const a=r.rows[0];if(a.status!=='initiated'||a.account_status!=='active'||!a.store_active||a.payment_method!=='UPI'||!payableStatuses.includes(a.order_status)){await c.query('ROLLBACK');return res.status(409).json({message:'This payment attempt is no longer eligible'});}const paid=await c.query(`SELECT COALESCE(sum(amount),0)::numeric(18,2) amount FROM payments WHERE dealer_order_id=$1 AND direction='in' AND status='posted'`,[id]);const due=Number((await c.query('SELECT GREATEST($1::numeric-$2::numeric,0)::numeric(18,2) amount',[a.accepted_total,paid.rows[0].amount])).rows[0].amount);if(Number(amount)>due||Number(amount)>Number(a.requested_amount)||(!a.dealer_partial_payments_enabled&&Number(amount)!==Number(a.requested_amount))){await c.query('ROLLBACK');return res.status(409).json({message:'Claimed amount exceeds the available balance or store payment policy'});}await c.query(`UPDATE dealer_manual_payment_claims SET claimed_amount=$3,utr_number=$4,paid_at=$5::timestamptz,status='pending_verification',screenshot_data=$6,screenshot_mime=$7,updated_at=now() WHERE id=$1 AND attempt_reference=$2`,[a.id,ref,amount,utr,paidAt,screenshot,mime]);await c.query(`UPDATE dealer_orders SET payment_status='PENDING_VERIFICATION',updated_at=now() WHERE id=$1`,[id]);await c.query(`INSERT INTO dealer_order_notifications(order_id,user_id,event_type) VALUES($1,$2,'DEALER_PAYMENT_SUBMITTED')`,[id,req.user.id]);await c.query(`INSERT INTO dealer_order_admin_notifications(order_id,event_type) VALUES($1,'PAYMENT_REVIEW')`,[id]);await c.query(`INSERT INTO audit_logs(store_id,user_id,action,entity_type,entity_id,after_data) VALUES($1,$2,'dealer.payment.claim_submitted','dealer_order',$3,$4)`,[a.store_id,req.user.id,id,{attemptReference:ref,claimedAmount:amount,utr}]);await c.query('COMMIT');return res.status(202).json({status:'PENDING_VERIFICATION',message:'Payment details submitted. Waiting for Admin verification.'});}catch(e){await c.query('ROLLBACK').catch(()=>{});if(e.code==='23505')return res.status(409).json({message:'This UTR has already been submitted for this store'});console.error('Manual UPI claim submission failed:',e.message);return res.status(500).json({message:'Unable to submit payment details'});}finally{c.release();}
}
export async function reviewManualUpiClaim(req,res){
 if(req.user?.userType!=='Admin')return res.status(403).json({message:'Admin access is required'});const claimId=req.params.claimId,action=req.body?.action,reason=String(req.body?.reason||'').trim();if(!idOk(claimId)||!['verify','reject'].includes(action)||action==='reject'&&(reason.length<3||reason.length>1000))return res.status(400).json({message:'Choose verify or provide a rejection reason'});const c=await connection.connect();try{await c.query('BEGIN');const r=await c.query(`SELECT a.*,o.order_number,o.status AS order_status,o.quotation_version,d.customer_id,d.user_id AS dealer_user_id,q.grand_total AS accepted_total FROM dealer_manual_payment_claims a JOIN dealer_orders o ON o.id=a.order_id JOIN dealer_profiles d ON d.id=a.dealer_id JOIN dealer_order_quotations q ON q.order_id=o.id AND q.version=o.quotation_version WHERE a.id=$1 FOR UPDATE OF a,o`,[claimId]);if(!r.rowCount){await c.query('ROLLBACK');return res.status(404).json({message:'Payment claim not found'});}const a=r.rows[0];if(!await canAccessStore(req.user,a.store_id)){await c.query('ROLLBACK');return res.status(403).json({message:'You do not have access to this store'});}if(a.status!=='pending_verification'){await c.query('ROLLBACK');return res.status(409).json({message:'This payment claim has already been reviewed'});}if(action==='reject'){await c.query(`UPDATE dealer_manual_payment_claims SET status='rejected',rejection_reason=$2,updated_at=now() WHERE id=$1`,[claimId,reason]);const paid=await c.query(`SELECT COALESCE(sum(amount),0)::numeric(18,2) amount FROM payments WHERE dealer_order_id=$1 AND direction='in' AND status='posted'`,[a.order_id]);const status=Number(paid.rows[0].amount)>=Number(a.accepted_total)?'PAID':Number(paid.rows[0].amount)>0?'PARTIALLY_PAID':'UNPAID';await c.query(`UPDATE dealer_orders SET payment_status=$2,updated_at=now() WHERE id=$1`,[a.order_id,status]);await c.query(`INSERT INTO dealer_order_notifications(order_id,user_id,event_type) VALUES($1,$2,'DEALER_PAYMENT_REJECTED')`,[a.order_id,a.dealer_user_id]);await c.query(`INSERT INTO audit_logs(store_id,user_id,action,entity_type,entity_id,after_data) VALUES($1,$2,'dealer.payment.claim_rejected','dealer_order',$3,$4)`,[a.store_id,req.user.id,a.order_id,JSON.stringify({claimId,reason})]);await c.query('COMMIT');return res.json({status:'rejected'});}
 const received=String(req.body?.verifiedAmount??a.claimed_amount);if(!validMoney(received)||Number(received)!==Number(a.claimed_amount)){await c.query('ROLLBACK');return res.status(400).json({message:'Verified amount must match the amount actually credited to the bank'});}const allPaid=await c.query(`SELECT COALESCE(sum(amount),0)::numeric(18,2) amount FROM payments WHERE dealer_order_id=$1 AND direction='in' AND status='posted'`,[a.order_id]);const totalAfter=Number(allPaid.rows[0].amount)+Number(received);if(totalAfter>Number(a.accepted_total)){await c.query('ROLLBACK');return res.status(409).json({message:'Verification would exceed the accepted order balance'});}const duplicate=await c.query(`SELECT id FROM payments WHERE store_id=$1 AND upper(reference)=upper($2) AND status='posted' AND payment_method='upi'`,[a.store_id,a.utr_number]);if(duplicate.rowCount){await c.query('ROLLBACK');return res.status(409).json({message:'This UTR already has a posted payment'});}const seq=await c.query(`SELECT nextval('customer_receipt_number_seq') AS value`);const requestKey=`dealer:manual-upi:${claimId}`,fp=createHash('sha256').update(`${a.order_id}:${a.utr_number}:${received}`).digest('hex');const payment=await c.query(`INSERT INTO payments(store_id,payment_number,direction,status,payment_method,amount,payment_date,reference,notes,created_by,customer_id,customer_request_key,request_fingerprint,dealer_order_id) VALUES($1,$2,'in','posted','upi',$3,$4::date,$5,$6,$7,$8,$9,$10,$11) RETURNING id,payment_number`,[a.store_id,`CR-${String(seq.rows[0].value).padStart(8,'0')}`,received,new Date(a.paid_at).toISOString().slice(0,10),a.utr_number,`Manually verified UPI payment for dealer order ${a.order_number}`,req.user.id,a.customer_id,requestKey,fp,a.order_id]);await allocateDealerReceiptIfInvoiced(c,a.order_id,payment.rows[0].id,a.store_id);await c.query(`UPDATE dealer_manual_payment_claims SET status='verified',payment_id=$2,verified_amount=$3,verified_by=$4,verified_at=now(),updated_at=now() WHERE id=$1`,[claimId,payment.rows[0].id,received,req.user.id]);const newTotal=await c.query(`SELECT COALESCE(sum(amount),0)::numeric(18,2) amount FROM payments WHERE dealer_order_id=$1 AND status='posted' AND direction='in'`,[a.order_id]);const status=Number(newTotal.rows[0].amount)>=Number(a.accepted_total)?'PAID':'PARTIALLY_PAID';await c.query(`UPDATE dealer_orders SET payment_status=$2,updated_at=now() WHERE id=$1`,[a.order_id,status]);await c.query(`INSERT INTO dealer_order_notifications(order_id,user_id,event_type) VALUES($1,$2,'DEALER_PAYMENT_VERIFIED')`,[a.order_id,a.dealer_user_id]);await c.query(`INSERT INTO audit_logs(store_id,user_id,action,entity_type,entity_id,after_data) VALUES($1,$2,'dealer.payment.claim_verified','payment',$3,$4)`,[a.store_id,req.user.id,payment.rows[0].id,JSON.stringify({claimId,orderId:a.order_id,utr:a.utr_number,amount:received,status})]);await c.query('COMMIT');return res.json({status,paymentNumber:payment.rows[0].payment_number,amount:received});
 }catch(e){await c.query('ROLLBACK').catch(()=>{});if(e.code==='23505')return res.status(409).json({message:'The UTR or payment claim has already been recorded'});console.error('Manual UPI claim review failed:',e.message);return res.status(500).json({message:'Unable to review payment claim'});}finally{c.release();}
}
export async function acceptQuotation(req,res){
 const orderId=req.params.id,version=Number(req.body?.quotationVersion);if(!idOk(orderId)||!Number.isInteger(version)||version<1)return res.status(400).json({message:'Provide the current quotationVersion'});
 const c=await connection.connect();try{await c.query('BEGIN');const p=await c.query(`SELECT d.id FROM dealer_profiles d JOIN stores s ON s.id=d.store_id WHERE d.user_id=$1 AND d.account_status='active' AND s.is_active=TRUE`,[req.user.id]);if(!p.rowCount){await c.query('ROLLBACK');return res.status(404).json({message:'Order not found'});}const o=await c.query('SELECT * FROM dealer_orders WHERE id=$1 AND dealer_id=$2 FOR UPDATE',[orderId,p.rows[0].id]);if(!o.rowCount){await c.query('ROLLBACK');return res.status(404).json({message:'Order not found'});}const order=o.rows[0];if(order.quotation_version!==version||!['QUOTATION_SENT','AWAITING_DEALER_ACCEPTANCE'].includes(order.status)){await c.query('ROLLBACK');return res.status(409).json({message:'Quotation changed or is not available; reload the latest version'});}const quote=await c.query('SELECT valid_until FROM dealer_order_quotations WHERE order_id=$1 AND version=$2',[orderId,version]);if(!quote.rowCount||quote.rows[0].valid_until&&new Date(quote.rows[0].valid_until)<new Date(new Date().toISOString().slice(0,10))){await c.query('ROLLBACK');return res.status(409).json({message:'Quotation has expired'});}await c.query(`UPDATE dealer_orders SET status='CONFIRMED',updated_at=now() WHERE id=$1`,[orderId]);await c.query(`INSERT INTO dealer_order_status_history(order_id,previous_status,new_status,changed_by,remarks) VALUES($1,$2,'CONFIRMED',$3,'Dealer accepted quotation version '||$4)`,[orderId,order.status,req.user.id,version]);await c.query('COMMIT');res.json({id:orderId,status:'CONFIRMED',quotationVersion:version,paymentStatus:order.payment_status});}catch(e){await c.query('ROLLBACK').catch(()=>{});console.error('Quotation acceptance failed:',e.message);res.status(500).json({message:'Unable to accept quotation'});}finally{c.release();}
}

export async function cancelOrder(req,res){
 req.body={...req.body,status:'CANCELLED'};return transitionOrder(req,res);
}

export async function listAdminOrderNotifications(req,res){
 try{const r=await connection.query(`SELECT n.id,n.event_type,n.created_at,o.id AS order_id,o.order_number,o.status,o.grand_total,d.business_name,d.contact_name FROM dealer_order_admin_notifications n JOIN dealer_orders o ON o.id=n.order_id JOIN dealer_profiles d ON d.id=o.dealer_id ORDER BY n.created_at DESC LIMIT 100`);res.json(r.rows);}catch(e){console.error('Dealer order notifications failed:',e.message);res.status(500).json({message:'Unable to load dealer order notifications'});}
}

export async function listDealerOrderNotifications(req,res){
 try{const r=await connection.query(`SELECT n.id,n.event_type,n.created_at,o.id AS order_id,o.order_number,o.status,o.quotation_number,o.quotation_version FROM dealer_order_notifications n JOIN dealer_orders o ON o.id=n.order_id WHERE n.user_id=$1 ORDER BY n.created_at DESC LIMIT 100`,[req.user.id]);res.json(r.rows);}catch(e){console.error('Dealer notifications failed:',e.message);res.status(500).json({message:'Unable to load notifications'});}
}

export async function listManualUpiClaims(req,res){
 if(req.user?.userType!=='Admin')return res.status(403).json({message:'Admin access is required'});try{const query=String(req.query.q||'').trim().slice(0,100),match=`%${query}%`;const rows=await connection.query(`SELECT a.id,a.order_id,a.dealer_id,a.store_id,a.attempt_reference,a.requested_amount,a.claimed_amount,a.utr_number,a.paid_at,a.status,a.verified_amount,a.rejection_reason,a.created_at,encode(a.screenshot_data,'base64') AS screenshot_data,a.screenshot_mime,o.order_number,o.grand_total AS order_total,d.business_name,s.name AS store_name FROM dealer_manual_payment_claims a JOIN dealer_orders o ON o.id=a.order_id JOIN dealer_profiles d ON d.id=a.dealer_id JOIN stores s ON s.id=a.store_id WHERE a.status IN ('pending_verification','rejected','verified') AND ($1='' OR o.order_number ILIKE $2 OR d.business_name ILIKE $2 OR d.mobile ILIKE $2 OR COALESCE(d.email,'') ILIKE $2 OR s.name ILIKE $2 OR a.utr_number ILIKE $2 OR a.attempt_reference ILIKE $2 OR a.status ILIKE $2 OR a.claimed_amount::text ILIKE $2 OR a.verified_amount::text ILIKE $2 OR a.paid_at::text ILIKE $2 OR a.created_at::text ILIKE $2) ORDER BY CASE a.status WHEN 'pending_verification' THEN 0 ELSE 1 END,a.created_at DESC LIMIT 300`,[query,match]);const allowed=[];for(const row of rows.rows)if(await canAccessStore(req.user,row.store_id))allowed.push(row);res.json(allowed);}catch(e){console.error('Manual UPI claims list failed:',e.message);res.status(500).json({message:'Unable to load UPI payment claims'});}
}

export async function listAdminDealerPayments(req,res){
 try{const query=String(req.query.q||'').trim().slice(0,100),match=`%${query}%`;const r=await connection.query(`SELECT o.id AS order_id,o.order_number,o.store_id,s.name AS store_name,d.business_name,d.contact_name,o.grand_total AS current_order_total,q.grand_total AS accepted_amount,o.payment_method,o.payment_status,COALESCE(p.received,0)::numeric(18,2) AS amount_received,GREATEST(q.grand_total-COALESCE(p.received,0),0)::numeric(18,2) AS remaining_balance,p.latest_reference,p.latest_payment_date,p.payment_history FROM dealer_orders o JOIN dealer_profiles d ON d.id=o.dealer_id JOIN stores s ON s.id=o.store_id LEFT JOIN dealer_order_quotations q ON q.order_id=o.id AND q.version=o.quotation_version LEFT JOIN LATERAL(SELECT sum(x.amount) FILTER(WHERE x.status='posted') AS received,max(x.payment_date) AS latest_payment_date,(array_agg(x.reference ORDER BY x.payment_date DESC,x.id DESC) FILTER(WHERE x.status='posted'))[1] AS latest_reference,jsonb_agg(jsonb_build_object('paymentId',x.id,'paymentNumber',x.payment_number,'amount',x.amount,'method',x.payment_method,'reference',x.reference,'paymentDate',x.payment_date,'status',x.status) ORDER BY x.id) FILTER(WHERE x.id IS NOT NULL) AS payment_history FROM payments x WHERE x.dealer_order_id=o.id) p ON TRUE WHERE ($1='' OR o.order_number ILIKE $2 OR d.business_name ILIKE $2 OR d.contact_name ILIKE $2 OR d.mobile ILIKE $2 OR COALESCE(d.email,'') ILIKE $2 OR s.name ILIKE $2 OR o.payment_method ILIKE $2 OR o.payment_status ILIKE $2 OR o.grand_total::text ILIKE $2 OR q.grand_total::text ILIKE $2 OR COALESCE(p.received,0)::text ILIKE $2 OR GREATEST(q.grand_total-COALESCE(p.received,0),0)::text ILIKE $2 OR COALESCE(p.latest_reference,'') ILIKE $2 OR EXISTS(SELECT 1 FROM payments x WHERE x.dealer_order_id=o.id AND (x.payment_number ILIKE $2 OR COALESCE(x.reference,'') ILIKE $2 OR x.amount::text ILIKE $2 OR x.payment_method ILIKE $2 OR x.payment_date::text ILIKE $2 OR x.status ILIKE $2)) OR EXISTS(SELECT 1 FROM dealer_manual_payment_claims a WHERE a.order_id=o.id AND (a.utr_number ILIKE $2 OR a.attempt_reference ILIKE $2 OR a.status ILIKE $2 OR a.claimed_amount::text ILIKE $2 OR a.paid_at::text ILIKE $2)) OR EXISTS(SELECT 1 FROM dealer_order_payment_attempts t WHERE t.order_id=o.id AND (COALESCE(t.provider_payment_id,'') ILIKE $2 OR COALESCE(t.provider_refund_id,'') ILIKE $2 OR t.amount::text ILIKE $2 OR t.status ILIKE $2 OR COALESCE(t.refund_status,'') ILIKE $2))) ORDER BY o.created_at DESC LIMIT 300`,[query,match]);const ids=r.rows.map(x=>x.order_id);const attempts=ids.length?await connection.query("SELECT id,order_id,provider_payment_id,amount,status,provider_refund_id,refund_status FROM dealer_order_payment_attempts WHERE order_id=ANY($1::bigint[]) ORDER BY id",[ids]):{rows:[]};for(const row of r.rows)row.payment_attempts=attempts.rows.filter(a=>String(a.order_id)===String(row.order_id));res.json(r.rows);}catch(e){console.error('Dealer payment list failed:',e.message);res.status(500).json({message:'Unable to load dealer payments'});}
}

export async function recordDealerCodCollection(req,res){
 const id=req.params.id,amount=String(req.body?.amount??''),key=String(req.get?.('Idempotency-Key')||req.headers?.['idempotency-key']||req.body?.idempotencyKey||''),reference=String(req.body?.reference||'').trim().slice(0,120);if(!idOk(id)||!/^\d{1,14}(\.\d{1,2})?$/.test(amount)||Number(amount)<=0)return res.status(400).json({message:'Provide an order ID and positive amount with up to two decimals'});if(key.length<8||key.length>100)return res.status(400).json({message:'Provide an Idempotency-Key of 8 to 120 characters'});if(!['Admin'].includes(req.user?.userType))return res.status(403).json({message:'Admin access is required'});
 const c=await connection.connect();try{await c.query('BEGIN');const o=await c.query(`SELECT o.*,d.customer_id,q.grand_total AS accepted_total FROM dealer_orders o JOIN dealer_profiles d ON d.id=o.dealer_id LEFT JOIN dealer_order_quotations q ON q.order_id=o.id AND q.version=o.quotation_version WHERE o.id=$1 FOR UPDATE OF o`,[id]);if(!o.rowCount){await c.query('ROLLBACK');return res.status(404).json({message:'Dealer order not found'});}const order=o.rows[0];if(!await canAccessStore(req.user,order.store_id)){await c.query('ROLLBACK');return res.status(403).json({message:'You do not have access to this store'});}if(order.payment_method!=='CASH_ON_DELIVERY'||!['CONFIRMED','PROCESSING','READY_TO_DISPATCH','SHIPPED','DELIVERED'].includes(order.status)){await c.query('ROLLBACK');return res.status(409).json({message:'COD collection is allowed only for an approved, active COD order'});}if(!order.customer_id){await c.query('ROLLBACK');return res.status(409).json({message:'This dealer is not linked to a customer ledger account'});}const prior=await c.query(`SELECT * FROM payments WHERE customer_request_key=$1 FOR UPDATE`,[`dealer:cod:${key}`]);if(prior.rowCount){const equalAmount=await c.query("SELECT $1::numeric=$2::numeric AS ok",[prior.rows[0].amount,amount]);if(String(prior.rows[0].dealer_order_id)!==String(id)||!equalAmount.rows[0].ok){await c.query('ROLLBACK');return res.status(409).json({message:'Idempotency key belongs to a different COD collection'});}await c.query('COMMIT');return res.json({paymentId:prior.rows[0].id,duplicate:true});}const total=await c.query(`SELECT COALESCE(sum(amount),0)::numeric(18,2) AS received FROM payments WHERE dealer_order_id=$1 AND status='posted'`,[id]);const limit=await c.query(`SELECT $1::numeric+$2::numeric<=$3::numeric AS allowed`,[total.rows[0].received,amount,order.accepted_total]);if(!limit.rows[0].allowed){await c.query('ROLLBACK');return res.status(409).json({message:'Collection exceeds the accepted quotation balance'});}const seq=await c.query(`SELECT nextval('customer_receipt_number_seq') AS value`);const fp=createHash('sha256').update(`${id}:${amount}:cash:${key}`).digest('hex');const p=await c.query(`INSERT INTO payments(store_id,payment_number,direction,status,payment_method,amount,payment_date,reference,notes,created_by,customer_id,customer_request_key,request_fingerprint,dealer_order_id) VALUES($1,$2,'in','posted','cash',$3,current_date,$4,$5,$6,$7,$8,$9,$10) RETURNING id,payment_number,payment_date,amount,payment_method,reference,status`,[order.store_id,`CR-${String(seq.rows[0].value).padStart(8,'0')}`,amount,reference||null,`COD collection for dealer order ${order.order_number}`,req.user.id,order.customer_id,`dealer:cod:${key}`,fp,id]);if(order.sales_invoice_id){const inv=await c.query(`SELECT total,status FROM sales_invoices WHERE id=$1 AND store_id=$2 FOR UPDATE`,[order.sales_invoice_id,order.store_id]);if(inv.rowCount&&inv.rows[0].status==='posted'){const received=await c.query(`SELECT COALESCE(sum(pa.amount),0)::numeric(18,2) amount FROM payment_allocations pa JOIN payments py ON py.id=pa.payment_id WHERE pa.sales_invoice_id=$1 AND py.status='posted'`,[order.sales_invoice_id]);const allocation=await c.query(`SELECT LEAST($1::numeric,GREATEST($2::numeric-$3::numeric,0))::numeric(18,2) amount`,[amount,inv.rows[0].total,received.rows[0].amount]);if(Number(allocation.rows[0].amount)>0)await c.query(`INSERT INTO payment_allocations(payment_id,store_id,direction,sales_invoice_id,amount) VALUES($1,$2,'in',$3,$4)`,[p.rows[0].id,order.store_id,order.sales_invoice_id,allocation.rows[0].amount]);}}const newTotal=await c.query(`SELECT sum(amount)::numeric(18,2) AS received FROM payments WHERE dealer_order_id=$1 AND status='posted'`,[id]);await c.query(`UPDATE dealer_orders SET payment_status=CASE WHEN $2::numeric>=$3::numeric THEN 'PAID' ELSE 'PARTIALLY_PAID' END,updated_at=now() WHERE id=$1`,[id,newTotal.rows[0].received,order.accepted_total]);await c.query(`INSERT INTO audit_logs(store_id,user_id,action,entity_type,entity_id,after_data) VALUES($1,$2,'dealer.payment.cod_collected','payment',$3,$4)`,[order.store_id,req.user.id,p.rows[0].id,{orderId:id,amount,reference}]);await c.query('COMMIT');return res.status(201).json({paymentId:p.rows[0].id,paymentNumber:p.rows[0].payment_number,amount:p.rows[0].amount,paymentMethod:'cash',paymentStatus:Number(newTotal.rows[0].received)>=Number(order.accepted_total)?'PAID':'PARTIALLY_PAID'});}catch(e){await c.query('ROLLBACK').catch(()=>{});console.error('COD collection failed:',e.message);return res.status(500).json({message:'Unable to record COD collection'});}finally{c.release();}
}

export async function initiateDealerRefund(req,res){
 const orderId=req.params.id,attemptId=req.params.attemptId;if(!idOk(orderId)||!idOk(attemptId)||req.user?.userType!=='Admin')return res.status(403).json({message:'Admin access is required'});const c=await connection.connect();try{await c.query('BEGIN');const r=await c.query(`SELECT a.*,o.store_id,o.status AS order_status,o.payment_status,o.order_number,p.reference AS provider_payment_reference FROM dealer_order_payment_attempts a JOIN dealer_orders o ON o.id=a.order_id JOIN payments p ON p.id=a.payment_id WHERE o.id=$1 AND a.id=$2 FOR UPDATE OF a,o,p`,[orderId,attemptId]);if(!r.rowCount){await c.query('ROLLBACK');return res.status(404).json({message:'Dealer payment attempt not found'});}const a=r.rows[0];if(!await canAccessStore(req.user,a.store_id)){await c.query('ROLLBACK');return res.status(403).json({message:'You do not have access to this store'});}if(!['CANCELLED','REJECTED'].includes(a.order_status)&&a.payment_status!=='REFUND_PENDING'){await c.query('ROLLBACK');return res.status(409).json({message:'A refund requires a canceled order or a flagged reconciliation'});}if(a.provider!=='razorpay'||!a.provider_payment_id||a.status==='refunded'||a.refund_status==='processed'){await c.query('ROLLBACK');return res.status(409).json({message:'This payment is not eligible for a provider refund'});}if(a.provider_refund_id){await c.query('COMMIT');return res.json({refundId:a.provider_refund_id,refundStatus:a.refund_status,duplicate:true});}const refund=await createRazorpayRefund(a.provider_payment_id,a.amount);if(!refund.id||String(refund.payment_id)!==String(a.provider_payment_id)||Number(refund.amount)!==Number(a.amount)*100){await c.query('ROLLBACK');return res.status(502).json({message:'Razorpay refund response did not match the payment'});}const status=['created','pending','processed','failed'].includes(refund.status)?refund.status:'pending';await c.query(`UPDATE dealer_order_payment_attempts SET status='refund_pending',provider_refund_id=$2,refund_status=$3,refund_requested_by=$4,refund_requested_at=now(),updated_at=now() WHERE id=$1`,[a.id,refund.id,status,req.user.id]);await c.query(`UPDATE dealer_orders SET payment_status='REFUND_PENDING',updated_at=now() WHERE id=$1`,[orderId]);await c.query(`INSERT INTO audit_logs(store_id,user_id,action,entity_type,entity_id,after_data) VALUES($1,$2,'dealer.payment.refund_requested','payment',$3,$4)`,[a.store_id,req.user.id,a.payment_id,{orderId,attemptId,refundId:refund.id,amount:a.amount,status}]);await c.query('COMMIT');return res.status(201).json({refundId:refund.id,refundStatus:status,amount:a.amount});}catch(e){await c.query('ROLLBACK').catch(()=>{});console.error('Dealer refund initiation failed:',e.message);return res.status(502).json({message:'Unable to initiate Razorpay refund'});}finally{c.release();}
}

export async function reconcileDealerRefund(req,res){
 const orderId=req.params.id,attemptId=req.params.attemptId;if(!idOk(orderId)||!idOk(attemptId)||req.user?.userType!=='Admin')return res.status(403).json({message:'Admin access is required'});const c=await connection.connect();try{await c.query('BEGIN');const r=await c.query(`SELECT a.*,o.store_id,o.order_number FROM dealer_order_payment_attempts a JOIN dealer_orders o ON o.id=a.order_id WHERE o.id=$1 AND a.id=$2 FOR UPDATE OF a,o`,[orderId,attemptId]);if(!r.rowCount){await c.query('ROLLBACK');return res.status(404).json({message:'Dealer refund not found'});}const a=r.rows[0];if(!await canAccessStore(req.user,a.store_id)){await c.query('ROLLBACK');return res.status(403).json({message:'You do not have access to this store'});}if(!a.provider_refund_id){await c.query('ROLLBACK');return res.status(409).json({message:'No provider refund has been requested'});}const provider=await getRazorpayRefund(a.provider_refund_id);if(String(provider.payment_id)!==String(a.provider_payment_id)||Number(provider.amount)!==Number(a.amount)*100){await c.query('ROLLBACK');return res.status(409).json({message:'Razorpay refund details do not match this order payment'});}if(provider.status!=='processed'){await c.query(`UPDATE dealer_order_payment_attempts SET refund_status=$2,updated_at=now() WHERE id=$1`,[a.id,['created','pending','failed'].includes(provider.status)?provider.status:'pending']);await c.query('COMMIT');return res.status(202).json({refundId:a.provider_refund_id,refundStatus:provider.status||'pending',reconciled:false});}const payment=await c.query(`SELECT * FROM payments WHERE id=$1 FOR UPDATE`,[a.payment_id]);if(payment.rowCount&&payment.rows[0].status==='posted')await c.query(`UPDATE payments SET status='reversed',reversal_reason=$2,reversed_by=$3,reversed_at=now() WHERE id=$1`,[a.payment_id,`Verified Razorpay refund ${a.provider_refund_id}`,req.user.id]);await c.query(`UPDATE dealer_order_payment_attempts SET status='refunded',refund_status='processed',refund_reconciled_at=now(),updated_at=now() WHERE id=$1`,[a.id]);const remains=await c.query(`SELECT EXISTS(SELECT 1 FROM payments WHERE dealer_order_id=$1 AND status='posted') AS outstanding`,[orderId]);await c.query(`UPDATE dealer_orders SET payment_status=CASE WHEN $2 THEN 'REFUND_PENDING' ELSE 'REFUNDED' END,updated_at=now() WHERE id=$1`,[orderId,remains.rows[0].outstanding]);await c.query(`INSERT INTO audit_logs(store_id,user_id,action,entity_type,entity_id,after_data) VALUES($1,$2,'dealer.payment.refund_reconciled','payment',$3,$4)`,[a.store_id,req.user.id,a.payment_id,{orderId,refundId:a.provider_refund_id,status:'processed'}]);await c.query('COMMIT');return res.json({refundId:a.provider_refund_id,refundStatus:'processed',reconciled:true,paymentStatus:remains.rows[0].outstanding?'REFUND_PENDING':'REFUNDED'});}catch(e){await c.query('ROLLBACK').catch(()=>{});console.error('Dealer refund reconciliation failed:',e.message);return res.status(502).json({message:'Unable to reconcile Razorpay refund'});}finally{c.release();}
}
